import java.util.Scanner;

class Animal {
    String name;

    Animal(String name) {
        this.name = name;
    }

    void speak() {
        System.out.println(name + "发出了一声叫");
    }
}

class Cat extends Animal {
    int fish;

    Cat(String name, int fish) {
        super(name);
        this.fish = fish;
    }

    @Override
    void speak() {
        System.out.println(name + "：喵～本喵有 " + fish + " 条小鱼干");
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int fish = sc.nextInt();
        Cat c = new Cat("{name}", fish);
        Animal a = new Animal("{other}");
        c.speak();
        a.speak();
        System.out.println("照猫图纸生的也是动物：" + (c instanceof Animal));
        System.out.println("照动物图纸生的不是猫：" + (a instanceof Cat));
    }
}
